{
  list = result;
  pagerange = book.getVariable("custom");
  if (typeof pagerange === 'string' && pagerange.trim() !== '') {
    startpage = parseInt(pagerange.split(',')[0]);
    endpage = parseInt(pagerange.split(',')[1]);
  } else {
    startpage = 2;
    endpage = 15;
  }
  if (isNaN(startpage) || isNaN(endpage)) {
    startpage = 2;
    endpage = 15;
  }
  prefix = book.tocUrl;
  if (Array.isArray(list) && list.length > 0) {
    lastpage = parseInt(list[list.length - 1].split('page=')[1]);
  } else {
    lastpage = endpage;
  }
  if (endpage < lastpage) {
    genlist = [];
    for (i = startpage; i <= endpage; i = i + 1) {
      nexturl = prefix + 'page=' + String(i);
      genlist.push(nexturl);
    }
    out = genlist;
  } else {
    out = list;
  }
  out;
}
</js>

