@css:main article@html
<js>
java.log(result);
var html = String(result || "");
function incChallenge(body) {
  var text = String(body || "").toLowerCase();
  return text.indexOf("datadome") >= 0 || text.indexOf("please enable js and disable any ad blocker") >= 0 || text.indexOf("enable javascript and cookies") >= 0 || text.indexOf("verify you are human") >= 0;
}
function incArticle(body) {
  {
    var d = org.jsoup.Jsoup.parse(String(body || ""));
    return String(d.select("article,main,[role=main],.article-body,.article-content,.content-body,.entry-content,.story-body").text()).trim().length > 500;
  }
}
function incUrlValue() {
  var u = String(baseUrl || ""), cut = u.indexOf(",{ ");
  if (cut < 0) cut = u.indexOf(",{");
  if (cut >= 0) u = u.substring(0, cut);
  if (u.indexOf("http://") !== 0 && u.indexOf("https://") !== 0) throw "Inc.com验证地址无效";
  return u;
}
html = String(result || "");
var incBlocked = incChallenge(html);
if (incBlocked) {
  var incUrl = incUrlValue();
  java.log("Inc.com DataDome challenge，尝试 WebView: " + incUrl);
  try {
    var autoHtml = String(java.webView(null, incUrl, null) || "");
    if (autoHtml && incArticle(autoHtml)) {
      html = autoHtml;
      incBlocked = false;
    }
  } catch (e) {
    common(java).networkError(e, java);
    java.log("Inc WebView refetch failed: " + e);
  }
  if (incBlocked) {
    java.log("Inc.com DataDome challenge，打开人工验证: " + incUrl);
    {
      html = String(java.startBrowserAwait(incUrl, "Inc.com人工验证", true).body());
    }
    if (incChallenge(html) && !incArticle(html)) throw "Inc.com人工验证未解除，请完成后重试";
  }
}
if (html.length < 5000 || (/展开以继续阅读|continue reading|read more/i).test(html)) {
  try {
    var u = String(baseUrl || "");
    var cut = u.indexOf(',{"webView"');
    if (cut >= 0) u = u.substring(0, cut);
    var full = java.webView(null, u, null);
    if (full && String(full).length > html.length) html = String(full);
  } catch (e) {
    common(java).networkError(e, java);
    java.log("Inc WebView refetch failed: " + e);
  }
}
var doc = org.jsoup.Jsoup.parseBodyFragment(html);
var candidates = doc.select("article,main,[role=main],.article-body,.article-content,.content-body,.entry-content,.story-body");
var best = null, bestScore = 0;
for (var i = 0; i < candidates.size(); i++) {
  var e = candidates.get(i), txt = "" + e.text(), cls = ("" + e.className()).toLowerCase();
  if (!txt || txt.length < 120) continue;
  var score = txt.length + e.select("p").size() * 180 + e.select("h2,h3").size() * 80;
  if ((/nav|menu|footer|sidebar|related|comment|social|advert|promo/).test(cls)) score -= txt.length;
  if (score > bestScore) {
    bestScore = score;
    best = e;
  }
}
if (!best) best = doc.body();
best.select('script,noscript,style,nav,header,footer,aside,form,.advertisement,.ad,.ads,.related,.social-share,.newsletter,.subscribe,.readMoreBtn,[class*="read-more"],[id*="readMore"],[id*="read-more"]').remove();
var imgs = best.select("img[src],img[data-src],img[data-original],img[data-lazy-src],img[data-srcset],img[srcset]");
function incJpg(value) {
  var text = String(value || '');
  if (text.toLowerCase().indexOf('img-cdn.inc.com/image/upload/') < 0) return text;
  return text.replace('f_webp', 'f_jpg').replace('.webp', '.jpg');
}
var imageAttrs = ['src', 'data-src', 'data-original', 'data-lazy-src', 'data-srcset', 'srcset'];
for (var imageIndex = 0; imageIndex < imgs.size(); imageIndex++) {
  var image = imgs.get(imageIndex);
  for (var attrIndex = 0; attrIndex < imageAttrs.length; attrIndex++) {
    var attrName = imageAttrs[attrIndex], attrValue = image.attr(attrName);
    if (attrValue) image.attr(attrName, incJpg(attrValue));
  }
}
result = "" + best.html();
result = common(java).TH(result, java, cache, {
  remove_selector: ["[aria-label=\"Eyebrow\"]", "button"]
});
result;
</js>

