function mathOf(el) {
  var outer = String(el.outerHtml());
  var start = outer.indexOf('<math');
  if (start >= 0) {
    var end = outer.indexOf('</math>', start);
    if (end >= 0) return outer.substring(start, end + 7);
  }
  return '';
}
function displayAlternatives(el) {
  if (String(el.tagName()).toLowerCase() !== 'disp-formula') return null;
  var anchor = el.parent();
  var sib = el.nextElementSibling();
  if (!sib && anchor) sib = anchor.nextElementSibling();
  if (sib && String(sib.tagName()).toLowerCase() === 'div' && sib.select('math').first()) return sib;
  return null;
}
var SPEECH_SYMBOLS = {
  '=': 'equals',
  '+': 'plus',
  '−': 'minus',
  '-': 'minus',
  '±': 'plus or minus',
  '×': 'times',
  '⋅': 'dot',
  '·': 'dot',
  '/': 'divided by',
  '∕': 'divided by',
  '<': 'less than',
  '>': 'greater than',
  '≤': 'less than or equal to',
  '≥': 'greater than or equal to',
  '≠': 'not equal to',
  '≈': 'approximately equal to',
  '∞': 'infinity',
  '∈': 'element of',
  '→': 'right arrow',
  '←': 'left arrow',
  '⇒': 'implies',
  ',': 'comma',
  '.': 'period',
  ':': 'colon',
  ';': 'semicolon',
  '(': 'left paren',
  ')': 'right paren',
  '[': 'left bracket',
  ']': 'right bracket',
  '{': 'left brace',
  '}': 'right brace',
  '|': 'vertical bar',
  '‖': 'double vertical bar',
  '′': 'prime',
  '…': 'dot dot dot',
  '∂': 'partial',
  '∇': 'del',
  '∀': 'for all',
  '∃': 'there exists',
  '⁡': '',
  '⁢': '',
  '⁣': '',
  '⁤': ''
};
var SPEECH_LARGE_OPS = {
  '∑': 'sum',
  '∏': 'product',
  '∫': 'integral'
};
var SPEECH_GREEK = {
  'α': 'alpha',
  'β': 'beta',
  'γ': 'gamma',
  'δ': 'delta',
  'ε': 'epsilon',
  'ζ': 'zeta',
  'η': 'eta',
  'θ': 'theta',
  'κ': 'kappa',
  'λ': 'lambda',
  'μ': 'mu',
  'ν': 'nu',
  'ξ': 'xi',
  'π': 'pi',
  'ρ': 'rho',
  'σ': 'sigma',
  'τ': 'tau',
  'φ': 'phi',
  'χ': 'chi',
  'ψ': 'psi',
  'ω': 'omega',
  'Γ': 'Gamma',
  'Δ': 'Delta',
  'Θ': 'Theta',
  'Λ': 'Lambda',
  'Π': 'Pi',
  'Σ': 'Sigma',
  'Φ': 'Phi',
  'Ω': 'Omega'
};
var SPEECH_ACCENTS = {
  '^': 'hat',
  'ˆ': 'hat',
  '¯': 'bar',
  '‾': 'bar',
  'ˉ': 'bar',
  '̄': 'bar',
  '→': 'vector',
  '⃗': 'vector',
  '~': 'tilde',
  '˜': 'tilde',
  '˙': 'dot',
  '¨': 'double dot'
};
function hasOwn(map, key) {
  return Object.prototype.hasOwnProperty.call(map, key);
}
function speechWord(text) {
  if (hasOwn(SPEECH_GREEK, text)) return SPEECH_GREEK[text];
  if (hasOwn(SPEECH_LARGE_OPS, text)) return SPEECH_LARGE_OPS[text];
  if (hasOwn(SPEECH_SYMBOLS, text)) return SPEECH_SYMBOLS[text];
  return text;
}
function mathSpeech(node) {
  var name = String(node.tagName()).toLowerCase();
  var kids = node.children();
  var n = kids.size();
  var text = String(node.text()).trim();
  function kid(i) {
    return i < n ? mathSpeech(kids.get(i)) : '';
  }
  function kidText(i) {
    return i < n ? String(kids.get(i).text()).trim() : '';
  }
  function all(sep) {
    var out = [];
    for (var i = 0; i < n; i++) {
      var s = mathSpeech(kids.get(i));
      if (s) out.push(s);
    }
    return out.join(sep);
  }
  switch (name) {
    case 'mi':
    case 'mn':
    case 'mo':
    case 'mtext':
      return speechWord(text);
    case 'msub':
      return kid(0) + ' sub ' + kid(1) + ' end sub';
    case 'msup':
      if (kidText(1) === '2') return kid(0) + ' squared';
      if (kidText(1) === '3') return kid(0) + ' cubed';
      return kid(0) + ' to the power of ' + kid(1) + ' end power';
    case 'msubsup':
      return kid(0) + ' sub ' + kid(1) + ' end sub to the power of ' + kid(2) + ' end power';
    case 'mfrac':
      return 'start fraction ' + kid(0) + ' over ' + kid(1) + ' end fraction';
    case 'msqrt':
      return 'square root of ' + all(' ') + ' end root';
    case 'mroot':
      return kid(1) + ' root of ' + kid(0) + ' end root';
    case 'munder':
      if (hasOwn(SPEECH_LARGE_OPS, kidText(0))) return speechWord(kidText(0)) + ' from ' + kid(1);
