    case 'munderover':
      if (hasOwn(SPEECH_LARGE_OPS, kidText(0))) return speechWord(kidText(0)) + ' from ' + kid(1) + ' to ' + kid(2) + ' of';
      return kid(0) + ' sub ' + kid(1) + ' end sub to the power of ' + kid(2) + ' end power';
    case 'mover':
      if (hasOwn(SPEECH_ACCENTS, kidText(1))) return kid(0) + ' ' + SPEECH_ACCENTS[kidText(1)];
      return kid(0) + ' with ' + kid(1) + ' above';
    case 'mtable':
      return 'matrix ' + all(' semicolon ') + ' end matrix';
    case 'mtr':
      return all(' comma ');
    case 'mspace':
    case 'mphantom':
    case 'none':
    case 'mprescripts':
    case 'annotation':
    case 'annotation-xml':
      return '';
    case 'semantics':
      return kid(0);
    default:
