var html = String(result);
var Jsoup = org.jsoup.Jsoup;
var doc = Jsoup.parse(html);
function formulaToImage(doc) {
  var formulas = doc.select('span.formula:has(> span.math), disp-formula, inline-formula');
  var converted = 0;
  var skipped = 0;
  var speechCount = 0;
  for (var i = 0; i < formulas.size(); i++) {
    var el = formulas.get(i);
    {
      var outer = String(el.outerHtml());
      var start = outer.indexOf('<math');
      var end = start >= 0 ? outer.indexOf('</math>', start) : -1;
      var mml = end >= 0 ? outer.substring(start, end + 7) : '';
      if (!mml) {
        java.log('ScienceDirect MathML not found in formula: ' + outer.substring(0, 240));
        skipped++;
        continue;
      }
      var speech = String(el.attr('data-semantic-speech') || '').trim();
      if (!speech) speech = String(el.text() || '').replace(/\\s+/g, ' ').trim();
      if (!speech) speech = mml.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim();
      var imageSrc = common(java).wirisSvg(mml, java);
      if (!imageSrc) {
        skipped++;
        continue;
      }
      var img = doc.createElement('img');
      img.attr('src', imageSrc);
      img.attr('alt', speech);
      el.replaceWith(img);
      if (speech) {
        var label = doc.createElement('span');
        label.addClass('formula-speech');
        label.addClass('notranslate');
        label.text(' ' + speech + ' ');
        img.after(label);
        speechCount++;
      }
      converted++;
    }
  }
  java.log('ScienceDirect MathML PNG POST: found=' + formulas.size() + ', converted=' + converted + ', speech=' + speechCount + ', skipped=' + skipped);
}
